import sympy

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def has_roots_mod_p(f, p):
    # Compute the polynomial f(x) mod p
    f_mod_p = f.subs(sympy.symbols('x'), sympy.symbols('x', mod=p))
    # Compute the discriminant of f(x) mod p
    discriminant = (3**2 - 4*1*3) % p
    # Check if the discriminant is a quadratic residue mod p
    return discriminant % p in [1, p-1]

# Check for odd primes p > 3
for p in range(7, 100, 2):
    if is_prime(p):
        f = sympy.symbols('x')**2 + 3*sympy.symbols('x') + 3
        if has_roots_mod_p(f, p):
            print(f"p = {p} has roots mod p")
        else:
            print(f"p = {p} does not have roots mod p")
